<?php require 'config.php';$u=require_admin();page_start('Administration',$u);heading('COMMUNITY OPERATIONS','Keep the community thriving.','Manage people, publish opportunities and understand participation.'); ?>
<div class="stats"><?php foreach(['users'=>'Members','registrations'=>'Registrations','progress'=>'Completed lessons','topics'=>'Discussions'] as $table=>$label)echo '<div><strong>'.one('SELECT COUNT(*) n FROM '.$table)['n'].'</strong><span>'.$label.'</span></div>';?></div>
<div class="inline"><a class="button secondary" href="report.php">Download engagement CSV ↓</a><a class="button secondary" href="report.php?type=events">Download event CSV ↓</a></div><br>
<?php
function admin_hidden(string $a,int $id=0): void {csrf();echo '<input type="hidden" name="action" value="'.$a.'"><input type="hidden" name="id" value="'.$id.'">';}
function event_form(?array $v=null): void {echo '<form class="card" method="post" action="action.php">';admin_hidden('event_save',(int)($v['id']??0));input('Title','title','text',$v['title']??'');textarea('Description','description',$v['description']??'');input('Date and time (Freetown)','starts_at','datetime-local',isset($v['starts_at'])?date('Y-m-d\TH:i',strtotime($v['starts_at'])):'');input('Location','location','text',$v['location']??'');input('Capacity','capacity','number',$v['capacity']??30);echo '<button class="button">Save event</button></form>';}
function resource_form(?array $v=null): void {echo '<form class="card" method="post" action="action.php">';admin_hidden('resource_save',(int)($v['id']??0));input('Title','title','text',$v['title']??'');input('Category','category','text',$v['category']??'');input('URL','url','url',$v['url']??'');textarea('Description','description',$v['description']??'');echo '<button class="button">Save resource</button></form>';}
?>
<div class="admin-grid"><details><summary>+ Publish an event</summary><?php event_form();?></details><details><summary>+ Add a learning resource</summary><?php resource_form();?></details></div>
<section class="card"><h2>Member management</h2><p>Assign mentors, manage roles and suspend accounts. Your own account is protected.</p><div class="table-wrap"><table><tr><th>Member</th><th>Role & status</th><th>Action</th></tr><?php foreach(rows('SELECT * FROM users ORDER BY id') as $m):?><tr><td><?=e($m['name'])?><br><?=e($m['email'])?></td><td colspan="2"><form class="inline" action="action.php" method="post"><?php admin_hidden('user_update',$m['id']);?><select aria-label="Role for <?=e($m['name'])?>" name="role"><?php foreach(['member','mentor','admin'] as $r)echo '<option '.($m['role']===$r?'selected':'').'>'.$r.'</option>';?></select><select aria-label="Account status" name="active"><option value="1" <?=$m['active']?'selected':''?>>Active</option><option value="0" <?=!$m['active']?'selected':''?>>Suspended</option></select><button class="ghost" <?=$m['id']===$u['id']?'disabled':''?>>Save</button></form></td></tr><?php endforeach;?></table></div></section>
<section class="card"><h2>Events & attendance</h2><?php foreach(rows('SELECT * FROM events ORDER BY starts_at DESC') as $ev):?><details><summary><?=e($ev['title'])?> · <?=e($ev['starts_at'])?></summary><?php event_form($ev);?><form action="action.php" method="post" data-confirm="Delete this event and all registrations?" class="inline"><?php admin_hidden('event_delete',$ev['id']);?><button class="ghost danger">Delete event</button></form><h3>Registered participants</h3><?php $participants=rows('SELECT r.*,u.name FROM registrations r JOIN users u ON u.id=r.user_id WHERE event_id=?',[$ev['id']]);foreach($participants as $r):?><form class="inline" method="post" action="action.php"><?php admin_hidden('attendance',$ev['id']);?><input type="hidden" name="user_id" value="<?=$r['user_id']?>"><strong><?=e($r['name'])?></strong><select name="attended" aria-label="Attendance"><option value="0" <?=!$r['attended']?'selected':''?>>Not attended</option><option value="1" <?=$r['attended']?'selected':''?>>Attended</option></select><button class="ghost">Record</button></form><?php endforeach;if(!$participants)echo '<p>No registrations.</p>';?></details><?php endforeach;?></section>
<section class="card"><h2>Learning materials</h2><?php foreach(rows('SELECT * FROM resources ORDER BY id') as $r):?><details><summary><?=e($r['title'])?></summary><?php resource_form($r);?><form method="post" action="action.php" data-confirm="Delete this resource and its progress records?"><?php admin_hidden('resource_delete',$r['id']);?><button class="ghost danger">Delete resource</button></form></details><?php endforeach;?></section>
<section class="card"><h2>Discussion moderation</h2><?php foreach(rows('SELECT id,title FROM topics ORDER BY id DESC') as $t):?><div class="discussion-row"><a href="community.php?topic=<?=$t['id']?>"><?=e($t['title'])?></a><form method="post" action="action.php" data-confirm="Delete this topic and all replies?"><?php admin_hidden('topic_delete',$t['id']);?><button class="ghost danger">Remove discussion</button></form></div><?php endforeach;?></section>
<section class="card"><h2>Recent activity audit</h2><div class="table-wrap"><table><tr><th>Actor</th><th>Action</th><th>Time</th></tr><?php foreach(rows('SELECT a.*,u.name FROM audit_log a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 30') as $a)echo '<tr><td>'.e($a['name']??'Deleted member').'</td><td>'.e($a['action']).'</td><td>'.e($a['created_at']).'</td></tr>';?></table></div></section><?php page_end(); ?>
